# First, the JSON pretty-printer
cat > /workspace/src/print.go << 'GOEOF'
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"math"
	"sort"
	"strconv"
	"strings"
)

// printValue prints a JSON value with pretty formatting
func printValue(w io.Writer, v interface{}, indent int, noInline bool) {
	printValueInner(w, v, indent, noInline, false)
}

func printValueInner(w io.Writer, v interface{}, indent int, noInline bool, inContainer bool) {
	if v == nil {
		fmt.Fprint(w, "null")
		return
	}

	switch val := v.(type) {
	case bool:
		if val {
			fmt.Fprint(w, "true")
		} else {
			fmt.Fprint(w, "false")
		}
	case float64:
		fmt.Fprint(w, formatNumber(val))
	case json.Number:
		fmt.Fprint(w, val.String())
	case string:
		fmt.Fprint(w, jsonEncodeString(val))
	case []interface{}:
		if !inContainer {
			// Top-level: always expand
			printArray(w, val, indent, noInline, false)
		} else if !noInline && isInlineArray(val) {
			// Can inline
			printArrayInline(w, val)
		} else {
			printArray(w, val, indent, noInline, false)
		}
	case map[string]interface{}:
		if len(val) == 0 {
			fmt.Fprint(w, "{}")
		} else {
			fmt.Fprint(w, "{\n")
			keys := sortedKeys(val)
			for i, k := range keys {
				printIndent(w, indent+1)
				fmt.Fprintf(w, "%s: ", jsonEncodeString(k))
				printValueInner(w, val[k], indent+1, noInline, true)
				if i < len(keys)-1 {
					fmt.Fprint(w, ",")
				}
				fmt.Fprint(w, "\n")
			}
			printIndent(w, indent)
			fmt.Fprint(w, "}")
		}
	default:
		// Fallback
		b, _ := json.Marshal(v)
		fmt.Fprint(w, string(b))
	}
}

func printArray(w io.Writer, arr []interface{}, indent int, noInline bool, allInlineChildren bool) {
	if len(arr) == 0 {
		fmt.Fprint(w, "[]")
		return
	}

	fmt.Fprint(w, "[\n")
	for i, elem := range arr {
		printIndent(w, indent+1)

		// For child arrays inside an array: check if all children are inline-able
		if childArr, ok := elem.([]interface{}); ok {
			if !noInline && allInlineChildren {
				printArrayInline(w, childArr)
			} else {
				printArray(w, childArr, indent+1, noInline, false)
			}
		} else {
			printValueInner(w, elem, indent+1, noInline, true)
		}

		if i < len(arr)-1 {
			fmt.Fprint(w, ",")
		}
		fmt.Fprint(w, "\n")
	}
	printIndent(w, indent)
	fmt.Fprint(w, "]")
}

func printArrayForObject(w io.Writer, arr []interface{}, indent int, noInline bool) {
	if len(arr) == 0 {
		fmt.Fprint(w, "[]")
		return
	}

	if !noInline && isInlineArray(arr) {
		printArrayInline(w, arr)
		return
	}

	// Check if array contains only arrays, and all of them are all-number non-empty
	allChildArraysInline := checkAllChildArraysInline(arr)

	fmt.Fprint(w, "[\n")
	for i, elem := range arr {
		printIndent(w, indent+1)

		if childArr, ok := elem.([]interface{}); ok {
			if !noInline && allChildArraysInline {
				printArrayInline(w, childArr)
			} else {
				printValueInner(w, elem, indent+1, noInline, true)
			}
		} else {
			printValueInner(w, elem, indent+1, noInline, true)
		}

		if i < len(arr)-1 {
			fmt.Fprint(w, ",")
		}
		fmt.Fprint(w, "\n")
	}
	printIndent(w, indent)
	fmt.Fprint(w, "]")
}

func checkAllChildArraysInline(arr []interface{}) bool {
	// All elements must be arrays
	for _, elem := range arr {
		childArr, ok := elem.([]interface{})
		if !ok {
			return false
		}
		if len(childArr) == 0 {
			return false // empty arrays break the group
		}
		if !isAllNumberArray(childArr) {
			return false
		}
	}
	return len(arr) > 0
}

func isInlineArray(arr []interface{}) bool {
	if len(arr) == 0 {
		return true
	}
	if len(arr) == 1 {
		// Single element: inline if not array or object
		switch arr[0].(type) {
		case []interface{}, map[string]interface{}:
			return false
		}
		return true
	}
	// Multiple elements: all must be numbers
	return isAllNumberArray(arr)
}

func isAllNumberArray(arr []interface{}) bool {
	for _, v := range arr {
		switch v.(type) {
		case float64:
			// OK
		case json.Number:
			// OK
		default:
			return false
		}
	}
	return true
}

func printArrayInline(w io.Writer, arr []interface{}) {
	if len(arr) == 0 {
		fmt.Fprint(w, "[]")
		return
	}
	fmt.Fprint(w, "[ ")
	for i, elem := range arr {
		if i > 0 {
			fmt.Fprint(w, ", ")
		}
		printValueInner(w, elem, 0, false, true)
	}
	fmt.Fprint(w, " ]")
}

func printIndent(w io.Writer, n int) {
	fmt.Fprint(w, strings.Repeat("  ", n))
}

func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func formatNumber(f float64) string {
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	if math.IsNaN(f) {
		return "null"
	}
	// Check if integer
	if f == math.Trunc(f) && !math.IsInf(f, 0) && math.Abs(f) < 1e15 {
		return strconv.FormatInt(int64(f), 10)
	}
	return strconv.FormatFloat(f, 'g', -1, 64)
}

func jsonEncodeString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

// outputValue outputs a value to w, treating strings specially (no quotes)
func outputValue(w io.Writer, v interface{}, noInline bool) error {
	if v == nil {
		fmt.Fprintln(w, "null")
		return nil
	}

	switch val := v.(type) {
	case string:
		fmt.Fprintln(w, val)
	case bool:
		if val {
			fmt.Fprintln(w, "true")
		} else {
			fmt.Fprintln(w, "false")
		}
	case float64:
		fmt.Fprintln(w, formatNumber(val))
	case json.Number:
		fmt.Fprintln(w, val.String())
	case jsUndefined:
		fmt.Fprintln(w, "undefined")
	case jsNull:
		fmt.Fprintln(w, "null")
	case []interface{}:
		printValueInner(w, val, 0, noInline, false)
		fmt.Fprintln(w)
	case map[string]interface{}:
		printValueInner(w, val, 0, noInline, false)
		fmt.Fprintln(w)
	default:
		fmt.Fprintln(w, v)
	}
	return nil
}
