#!/usr/bin/env python3
"""fx - Terminal JSON viewer and processor"""

import sys
import os
import json
import re
import signal
from typing import Any, Optional

VERSION = "39.2.0"

# JavaScript runtime types
class JSUndefined:
    def __repr__(self): return 'undefined'
    def __str__(self): return 'undefined'
    def __eq__(self, other): return isinstance(other, JSUndefined)

class JSNull:
    def __repr__(self): return 'null'
    def __str__(self): return 'null'
    def __eq__(self, other): return other is None or isinstance(other, JSNull)

UNDEFINED = JSUndefined()
NULL = JSNull()

class JSObject:
    """Mimics JavaScript object with property access"""
    def __init__(self, data, keys=None):
        if isinstance(data, dict):
            self._data = data
            self._keys = keys if keys is not None else list(data.keys())
        else:
            self._data = data
            self._keys = []

    def __getattr__(self, name):
        if name.startswith('_'):
            return object.__getattribute__(self, name)
        data = object.__getattribute__(self, '_data')
        if isinstance(data, dict) and name in data:
            return to_js(data[name])
        raise JSTypeError(f"Cannot read property '{name}' of " + 
                         ("undefined" if isinstance(data, JSUndefined) else str(data)))

    def __getitem__(self, key):
        data = object.__getattribute__(self, '_data')
        if isinstance(data, dict):
            if key in data:
                return to_js(data[key])
            return UNDEFINED
        elif isinstance(data, list):
            if isinstance(key, int) and 0 <= key < len(data):
                return to_js(data[key])
            return UNDEFINED
        return UNDEFINED

class JSError(Exception):
    def __init__(self, msg, error_type="Error"):
        self.error_type = error_type
        super().__init__(msg)

class JSTypeError(JSError):
    def __init__(self, msg):
        super().__init__(msg, "TypeError")

class JSReferenceError(JSError):
    def __init__(self, msg):
        super().__init__(msg, "ReferenceError")

class JSSyntaxError(JSError):
    def __init__(self, msg):
        super().__init__(msg, "SyntaxError")

def to_js(v):
    """Convert Python value to JS-compatible value"""
    if isinstance(v, dict):
        return OrderedJSDict(v)
    elif isinstance(v, list):
        return JSArray(v)
    elif v is None:
        return None  # null
    elif isinstance(v, bool):
        return v
    elif isinstance(v, (int, float)):
        return v
    elif isinstance(v, str):
        return v
    elif isinstance(v, (JSUndefined, JSNull)):
        return v
    return v

def from_js(v):
    """Convert JS value back to Python native"""
    if isinstance(v, OrderedJSDict):
        return v._dict
    elif isinstance(v, JSArray):
        return v._list
    elif isinstance(v, JSUndefined):
        return UNDEFINED
    return v

class OrderedJSDict:
    """JavaScript object with ordered keys"""
    def __init__(self, d, keys=None):
        self._dict = d if isinstance(d, dict) else {}
        self._keys = keys if keys is not None else list(d.keys())

    def __getattr__(self, name):
        if name.startswith('_'):
            return object.__getattribute__(self, name)
        d = object.__getattribute__(self, '_dict')
        if name in d:
            return to_js(d[name])
        return UNDEFINED

    def __setattr__(self, name, value):
        if name.startswith('_'):
            object.__setattr__(self, name, value)
        else:
            self._dict[name] = from_js(value)
            if name not in self._keys:
                self._keys.append(name)

    def __getitem__(self, key):
        d = object.__getattribute__(self, '_dict')
        if key in d:
            return to_js(d[key])
        return UNDEFINED

    def __setitem__(self, key, value):
        self._dict[key] = from_js(value)
        if key not in self._keys:
            self._keys.append(key)

    def __contains__(self, key):
        return key in self._dict

    def __repr__(self):
        return json.dumps(self._dict)

    def keys(self):
        return JSArray(list(self._keys))

    def values(self):
        return JSArray([to_js(v) for v in self._dict.values()])

    def entries(self):
        return JSArray([[k, to_js(v)] for k, v in self._dict.items()])

    def hasOwnProperty(self, key):
        return key in self._dict

    @property
    def length(self):
        return len(self._dict)

class JSArray:
    """JavaScript array"""
    def __init__(self, lst):
        self._list = [from_js(item) for item in lst] if lst else []

    def __getattr__(self, name):
        if name.startswith('_'):
            return object.__getattribute__(self, name)
        lst = object.__getattribute__(self, '_list')
        if name == 'length':
            return len(lst)
        # Array methods
        if name == 'map':
            def map_fn(fn):
                return JSArray([from_js(fn(to_js(item))) for item in lst])
            return map_fn
        if name == 'filter':
            def filter_fn(fn):
                return JSArray([item for item in lst if fn(to_js(item))])
            return filter_fn
        if name == 'reduce':
            def reduce_fn(fn, initial=None):
                if initial is None:
                    if not lst: raise JSTypeError("Reduce of empty array with no initial value")
                    acc = to_js(lst[0])
                    for item in lst[1:]:
                        acc = fn(acc, to_js(item))
                    return acc
                else:
                    acc = initial
                    for item in lst:
                        acc = fn(acc, to_js(item))
                    return acc
            return reduce_fn
        if name == 'forEach':
            def foreach_fn(fn):
                for i, item in enumerate(lst):
                    fn(to_js(item), i, self)
            return foreach_fn
        if name == 'find':
            def find_fn(fn):
                for item in lst:
                    if fn(to_js(item)):
                        return to_js(item)
                return UNDEFINED
            return find_fn
        if name == 'findIndex':
            def find_idx_fn(fn):
                for i, item in enumerate(lst):
                    if fn(to_js(item)):
                        return i
                return -1
            return find_idx_fn
        if name == 'some':
            def some_fn(fn):
                return any(fn(to_js(item)) for item in lst)
            return some_fn
        if name == 'every':
            def every_fn(fn):
                return all(fn(to_js(item)) for item in lst)
            return every_fn
        if name == 'includes':
            def includes_fn(val):
                return from_js(val) in lst
            return includes_fn
        if name == 'indexOf':
            def index_of_fn(val):
                try:
                    return lst.index(from_js(val))
                except ValueError:
                    return -1
            return index_of_fn
        if name == 'join':
            def join_fn(sep=','):
                return sep.join(str(item) for item in lst)
            return join_fn
        if name == 'slice':
            def slice_fn(start=None, end=None):
                return JSArray(lst[start:end])
            return slice_fn
        if name == 'sort':
            def sort_fn(fn=None):
                import copy
                new_lst = copy.copy(lst)
                if fn is None:
                    new_lst.sort(key=lambda x: str(x) if x is not None else '')
                else:
                    import functools
                    def cmp(a, b):
                        result = fn(to_js(a), to_js(b))
                        if isinstance(result, (int, float)):
                            return int(result)
                        return 0
                    new_lst.sort(key=functools.cmp_to_key(cmp))
                return JSArray(new_lst)
            return sort_fn
        if name == 'reverse':
            def reverse_fn():
                return JSArray(list(reversed(lst)))
            return reverse_fn
        if name == 'concat':
            def concat_fn(*args):
                result = list(lst)
                for arg in args:
                    if isinstance(arg, JSArray):
                        result.extend(arg._list)
                    else:
                        result.append(from_js(arg))
                return JSArray(result)
            return concat_fn
        if name == 'flat':
            def flat_fn(depth=1):
                def do_flat(arr, d):
                    result = []
                    for item in arr:
                        if isinstance(item, (list, JSArray)) and d > 0:
                            sub = item._list if isinstance(item, JSArray) else item
                            result.extend(do_flat(sub, d-1))
                        else:
                            result.append(item)
                    return result
                return JSArray(do_flat(lst, depth))
            return flat_fn
        if name == 'flatMap':
            def flat_map_fn(fn):
                result = []
                for item in lst:
                    r = from_js(fn(to_js(item)))
                    if isinstance(r, list):
                        result.extend(r)
                    elif isinstance(r, JSArray):
                        result.extend(r._list)
                    else:
                        result.append(r)
                return JSArray(result)
            return flat_map_fn
        if name == 'push':
            def push_fn(*items):
                for item in items:
                    lst.append(from_js(item))
                return len(lst)
            return push_fn
        if name == 'pop':
            def pop_fn():
                if lst:
                    return to_js(lst.pop())
                return UNDEFINED
            return pop_fn
        if name == 'shift':
            def shift_fn():
                if lst:
                    return to_js(lst.pop(0))
                return UNDEFINED
            return shift_fn
        if name == 'unshift':
            def unshift_fn(*items):
                for i, item in enumerate(items):
                    lst.insert(i, from_js(item))
                return len(lst)
            return unshift_fn
        if name == 'splice':
            def splice_fn(start, delete_count=None, *items):
                end = start if delete_count is None else start + delete_count
                removed = lst[start:end]
                lst[start:end] = [from_js(item) for item in items]
                return JSArray(removed)
            return splice_fn
        if name == 'fill':
            def fill_fn(val, start=0, end=None):
                end = len(lst) if end is None else end
                for i in range(start, end):
                    lst[i] = from_js(val)
                return self
            return fill_fn
        if name == 'entries':
            def entries_fn():
                return JSArray([[i, to_js(item)] for i, item in enumerate(lst)])
            return entries_fn
        if name == 'keys':
            def keys_fn():
                return JSArray(list(range(len(lst))))
            return keys_fn
        if name == 'values':
            def values_fn():
                return JSArray(list(lst))
            return values_fn
        if name == 'toString':
            def to_string_fn():
                return ','.join(str(item) for item in lst)
            return to_string_fn
        return UNDEFINED

    def __getitem__(self, key):
        lst = object.__getattribute__(self, '_list')
        if isinstance(key, int):
            if 0 <= key < len(lst):
                return to_js(lst[key])
            if -len(lst) <= key < 0:
                return to_js(lst[key])
            return UNDEFINED
        return UNDEFINED

    def __setitem__(self, key, value):
        lst = object.__getattribute__(self, '_list')
        if isinstance(key, int):
            while key >= len(lst):
                lst.append(None)
            lst[key] = from_js(value)

    def __len__(self):
        return len(self._list)

    def __iter__(self):
        return iter(self._list)

    def __repr__(self):
        return json.dumps(self._list)

    def __contains__(self, item):
        return from_js(item) in self._list

    def __bool__(self):
        return True  # Arrays are always truthy in JS

