# ======================================================
# JavaScript expression evaluator
# ======================================================

import ast
import re

# Transform JS expression to Python
def transform_expr(expr):
    """Transform JS expression to Python evaluatable code"""
    # Special cases
    if expr == '.':
        return '_x_'
    if expr == '.[]':
        return '_flatten_(_x_)'

    # If starts with '.', prepend '_x_'
    if expr.startswith('.'):
        transformed = '_x_' + expr[1:]
    else:
        transformed = expr

    return transformed

def js_to_python(code):
    """Attempt to translate JS code to Python"""
    if not code:
        return code

    # Replace 'x' with '_x_' for safety
    # Actually, keep it as 'x' for the main variable

    # Handle arrow functions: (params) => body or param => body
    # Simple single-expression arrow functions
    def replace_arrow_multi(m):
        params = m.group(1).strip()
        body = m.group(2).strip()
        if params.startswith('(') and params.endswith(')'):
            params = params[1:-1]
        # Handle destructuring params like {name, age}
        params = clean_params(params)
        body_py = js_to_python(body)
        return f"(lambda {params}: {body_py})"

    # Arrow functions with parenthesized params
    code = re.sub(r'\(([^)(]*)\)\s*=>\s*((?:[^,\)\]]+|\[.*?\]|\{.*?\})+)', replace_arrow_multi, code)
