# ======================================================
# Evaluate expression against value
# ======================================================

def evaluate_expr(expr_orig, x_val, strict=False):
    """Evaluate a JS expression with x as the current value"""

    # Special cases
    if expr_orig == '.':
        return x_val

    if expr_orig == '.[]':
        # Flatten one level
        if isinstance(x_val, (list, JSArray)):
            lst = x_val._list if isinstance(x_val, JSArray) else x_val
            result = []
            for item in lst:
                if isinstance(item, (list, JSArray)):
                    sub = item._list if isinstance(item, JSArray) else item
                    result.extend(sub)
                else:
                    result.append(item)
            return JSArray(result)
        raise JSTypeError("Object has no member 'flatMap'")

    # Transform expression
    if expr_orig.startswith('.'):
        expr = 'x' + expr_orig[1:]
        expr_displayed = 'x' + expr_orig
        has_transform = True
    else:
        expr = expr_orig
        expr_displayed = None
        has_transform = False

    # Convert JS to Python
    py_expr = js_to_python(expr)

    # Create environment
    env = create_js_env(x_val)

    try:
        result = eval(py_expr, {"__builtins__": {}}, env)
        return result
    except (SyntaxError, TypeError, AttributeError, IndexError, KeyError) as e:
        raise e
    except NameError as e:
        name = str(e).split("'")[1] if "'" in str(e) else str(e)
        raise JSReferenceError(f"{name} is not defined")
    except Exception as e:
        raise e

def format_error_output(expr_orig, error_msg):
    """Format error output to match fx's error format"""
    lines = [
        "",
        f"  {expr_orig}",
        f"  {'~' * len(expr_orig)}",
        "",
    ]

    if expr_orig.startswith('.'):
        transformed = 'x' + expr_orig
        lines.extend([transformed, ""])

    lines.append(error_msg)
    return "\n".join(lines)

