            if n in ('_UNDEF_', 'UNDEFINED'): n = 'undefined'
            raise JSError("ReferenceError", f"{n} is not defined")
        raise JSError("ReferenceError", name)
    except AttributeError as e:
        msg = str(e)
        # Convert Python AttributeError to JS TypeError
        m = re.search(r"'([^']+)' object has no attribute '([^']+)'", msg)
        if m:
            obj_type = m.group(1)
            attr = m.group(2)
            raise JSError("TypeError", f"Cannot read property '{attr}' of undefined")
        raise JSError("TypeError", msg)
    except TypeError as e:
        msg = str(e)
        raise JSError("TypeError", msg)
    except JSError:
        raise
    except Exception as e:
        raise JSError("Error", str(e))

def format_syntax_error(expr, msg):
    """Format a Python syntax error like a JS error"""
    # Common translations
    if 'unexpected EOF' in msg.lower():
        return "Unexpected end of input"
    if 'invalid syntax' in msg.lower():
        return f"Unexpected token {msg}"
    return msg

def format_error_block(expr_orig, error):
    """Format error output to match fx's error format"""
    lines = [
