        f"  {expr_orig}",
        f"  {'~' * len(expr_orig)}",
        "",
    ]

    if expr_orig.startswith('.'):
        lines.append('x' + expr_orig)
        lines.append("")

    if isinstance(error, JSError):
        lines.append(f"{error.error_type}: {error.message}")
    else:
        lines.append(str(error))

    return "\n".join(lines)

