def format_number(f):
    """Format a number for output"""
    if isinstance(f, bool):
        return 'true' if f else 'false'
    if isinstance(f, int):
        return str(f)
    if math.isnan(f):
        return 'null'
    if math.isinf(f):
        return 'Infinity' if f > 0 else '-Infinity'
    # For floats: if it's a whole number, show as int
    if f == int(f) and abs(f) < 1e15:
        return str(int(f))
    # Use Python's repr for float representation
    s = repr(f)
    return s

def is_number(v):
    """Check if v is a JSON number (not bool)"""
    if isinstance(v, bool): return False
    if isinstance(v, (int, float)): return True
    if isinstance(v, JSObj):
        inner = object.__getattribute__(v, '_val')
        return is_number(inner)
    return False

def get_native(v):
    """Get native Python value from JSObj"""
    if isinstance(v, JSObj):
        return object.__getattribute__(v, '_val')
    return v

def is_inline_array(lst):
    """Check if array can be printed inline (when nested inside object/array)"""
    if len(lst) == 0:
        return True
    if len(lst) == 1:
        item = get_native(lst[0])
        # Single element: inline if not array or object
        return not isinstance(item, (list, dict, OrderedDict))
    # Multiple: all must be numbers
    return all(is_number(item) for item in lst)

def check_all_child_arrays_number(lst):
    """Check if all elements are non-empty number arrays"""
    for elem in lst:
        v = get_native(elem)
        if not isinstance(v, list):
            return False
        if len(v) == 0:
            return False
        if not all(is_number(x) for x in v):
            return False
    return len(lst) > 0

def format_value(v, indent=0, no_inline=False):
    """Format a value for printing (when it's a nested value inside a container)"""
    v = get_native(v)

    if v is None:
        return "null"
    if isinstance(v, JSUndefined):
        return "undefined"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return format_number(v)
    if isinstance(v, str):
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, (list, dict, OrderedDict)):
        if isinstance(v, list):
            return format_array_nested(v, indent, no_inline)
        else:
            return format_object(v, indent, no_inline)
    return str(v)

