            formatted = "[ " + ", ".join(parts) + " ]"
        else:
            formatted = format_value(item, indent + 1, no_inline)
        lines.append(ind + formatted)

    outer = "  " * indent
    return "[\n" + ",\n".join(lines) + "\n" + outer + "]"

def format_object(d, indent, no_inline):
