    outer = "  " * indent
    parts = []

    for k in keys:
        v = d[k]
        key_str = json.dumps(k, ensure_ascii=False)
        val_str = format_value(v, indent + 1, no_inline)
        parts.append(f"{ind}{key_str}: {val_str}")

