def format_top_level(v, no_inline=False):
    """Format a top-level value for output"""
    v_native = get_native(v)

    if v_native is None:
        return "null"
    if isinstance(v_native, JSUndefined):
        return "undefined"
    if isinstance(v_native, bool):
        return "true" if v_native else "false"
    if isinstance(v_native, int):
        return str(v_native)
    if isinstance(v_native, float):
        return format_number(v_native)
    if isinstance(v_native, str):
        return v_native  # strings: no quotes at top level
    if isinstance(v_native, list):
        # Top-level arrays: always expand
        if len(v_native) == 0:
            return "[]"
        ind = "  "
        lines = []
        for item in v_native:
            lines.append(ind + format_value(item, 1, no_inline))
        return "[\n" + ",\n".join(lines) + "\n]"
    if isinstance(v_native, (dict, OrderedDict)):
        return format_object(v_native, 0, no_inline)
    return str(v_native)

def output_value(v, no_inline=False):
    """Output a value"""
    formatted = format_top_level(v, no_inline)
    print(formatted)

