def parse_toml(text):
    """Parse TOML to Python OrderedDict"""
    # Use the tomli library if available
    try:
        import tomli
        result = tomli.loads(text)
        return _to_ordered_dict(result)
    except ImportError:
        pass

    # Fallback: basic TOML parser
    return _parse_toml_basic(text)

def _to_ordered_dict(v):
    """Convert nested dict to OrderedDict"""
    if isinstance(v, dict):
        od = OrderedDict()
        for k, val in v.items():
            od[k] = _to_ordered_dict(val)
        return od
    if isinstance(v, list):
        return [_to_ordered_dict(item) for item in v]
    return v

def _parse_toml_basic(text):
    """Very basic TOML parser"""
    result = OrderedDict()
    current = result
    current_path = []

    lines = text.split('\n')

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        # Section header
        if line.startswith('[') and line.endswith(']') and not line.startswith('[['):
            path = line[1:-1].strip()
            keys = [k.strip() for k in path.split('.')]
            current = result
            for key in keys:
                if key not in current:
                    current[key] = OrderedDict()
                current = current[key]
            current_path = keys
            continue

        # Array section header
        if line.startswith('[[') and line.endswith(']]'):
            path = line[2:-2].strip()
            keys = [k.strip() for k in path.split('.')]
            current = result
            for key in keys[:-1]:
                if key not in current:
                    current[key] = OrderedDict()
                current = current[key]
            last_key = keys[-1]
            if last_key not in current:
                current[last_key] = []
            new_item = OrderedDict()
            current[last_key].append(new_item)
            current = new_item
            current_path = keys
            continue

        # Key = value
        if '=' in line:
            eq_idx = line.index('=')
            key = line[:eq_idx].strip()
            value_str = line[eq_idx+1:].strip()

            # Remove inline comment
            value_str = _toml_remove_comment(value_str)

            value = _parse_toml_value(value_str)
            current[key] = value

    return result

def _toml_remove_comment(s):
    """Remove inline comment from TOML value"""
    # Simple: find # outside of strings
    in_str = None
    for i, c in enumerate(s):
        if in_str:
            if c == '\\': continue
            if c == in_str: in_str = None
        elif c in ('"', "'"):
            in_str = c
        elif c == '#':
            return s[:i].strip()
    return s.strip()

def _parse_toml_value(s):
    """Parse a TOML value"""
    s = s.strip()

    if s.startswith('"') and s.endswith('"'):
        # String
        return json.loads(s)
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1]
    if s.startswith('"""') and s.endswith('"""'):
        return s[3:-3]
    if s.startswith("'''") and s.endswith("'''"):
        return s[3:-3]
    if s == 'true': return True
    if s == 'false': return False
    if s.startswith('[') and s.endswith(']'):
        # Inline array
        inner = s[1:-1].strip()
        if not inner:
            return []
        items = _split_toml_array(inner)
        return [_parse_toml_value(item.strip()) for item in items]
    if s.startswith('{') and s.endswith('}'):
        # Inline table
        inner = s[1:-1].strip()
        result = OrderedDict()
        if not inner:
            return result
        pairs = _split_toml_array(inner)
        for pair in pairs:
            k, v = pair.split('=', 1)
            result[k.strip()] = _parse_toml_value(v.strip())
        return result

    # Try number
    try:
        if '.' in s or 'e' in s.lower():
            return float(s)
        return int(s)
    except ValueError:
        pass

    return s

def _split_toml_array(s):
    """Split array items handling nested brackets"""
    items = []
    depth = 0
    current = ''
    in_str = None

    for c in s:
        if in_str:
            current += c
            if c == in_str: in_str = None
        elif c in ('"', "'"):
            in_str = c
            current += c
        elif c in ('[', '{'):
            depth += 1
            current += c
        elif c in (']', '}'):
            depth -= 1
            current += c
        elif c == ',' and depth == 0:
            items.append(current.strip())
            current = ''
        else:
            current += c

    if current.strip():
        items.append(current.strip())

    return items

