# ======================================================
# Completion mode
# ======================================================

def complete_zsh(line):
    """Handle ZSH completion"""
    parts = line.split()
    if len(parts) < 1:
        return

    # If we have less than 2 args (just 'fx'), list files
    if len(parts) < 2:
        _list_files('', zsh=True)
        return

    # Check if second arg looks like a file
    possible_file = parts[1] if len(parts) > 1 else ''

    if len(parts) == 2 and not line.endswith(' '):
        # We're completing the first arg (file)
        _list_files(possible_file, zsh=True)
        return

    if len(parts) >= 2:
        file_arg = parts[1]
        if not os.path.exists(file_arg) and not possible_file.startswith('.'):
            _list_files(possible_file, zsh=True)
            return

        # Have a file, completing the expression
        try:
            with open(file_arg, 'r') as f:
                data = json.load(f, object_pairs_hook=OrderedDict)
        except:
            return

        # Get current expression
        if len(parts) == 2:
            # No expression yet or space after file
            expr = '' if line.endswith(' ') else ''
        else:
            expr = parts[-1]

        _complete_expression(data, expr, zsh=True)

def complete_fish(line):
    """Handle Fish completion"""
    parts = line.split()
    if len(parts) < 1:
        return

    # Similar to ZSH but different format
    if len(parts) < 2:
        _list_files('', zsh=False)
        return

    if len(parts) == 2 and not line.endswith(' '):
        _list_files(parts[1], zsh=False)
        return

    if len(parts) >= 2:
        file_arg = parts[1]
        if not os.path.exists(file_arg):
            _list_files(parts[1] if len(parts) > 1 else '', zsh=False)
            return

        try:
            with open(file_arg, 'r') as f:
                data = json.load(f, object_pairs_hook=OrderedDict)
        except:
            return

        expr = '' if line.endswith(' ') else parts[-1] if len(parts) > 2 else ''
        _complete_expression(data, expr, zsh=False)

def _list_files(prefix, zsh=True):
    """List files matching prefix"""
    import glob

    # Get directory and base
    if prefix.endswith('/'):
        dir_part = prefix
        base_part = ''
    elif '/' in prefix:
        dir_part = prefix[:prefix.rfind('/')+1]
        base_part = prefix[prefix.rfind('/')+1:]
    else:
        dir_part = ''
        base_part = prefix

    search_dir = dir_part if dir_part else '.'

    try:
        entries = os.listdir(search_dir)
    except OSError:
        return

    for entry in sorted(entries):
        if not entry.startswith(base_part):
            continue
        if entry.startswith('.') and not base_part.startswith('.'):
            continue

        full_path = os.path.join(search_dir, entry) if search_dir != '.' else entry
        display_path = dir_part + entry

        if os.path.isdir(full_path):
            if zsh:
                print(f"{display_path}/\t{display_path}\tfile")
            else:
                print(f"{display_path}")
        else:
            if zsh:
                print(f"{display_path}\t{display_path}\tfile")
            else:
                print(f"{display_path}")

def _complete_expression(data, expr, zsh=True):
    """Complete a JSON path expression"""
    # Navigate to the current level
    if expr.startswith('.'):
        parts = expr.split('.')
        # Navigate through the path
        current = data
        completed_parts = []

        # Find how far we can navigate
        for i, part in enumerate(parts[1:], 1):  # skip leading '.'
            if not part:
                # At this level, list keys
                if isinstance(current, (dict, OrderedDict)):
                    prefix = '.'.join(parts[:i])
                    for key in current.keys():
                        key_str = f".{key}"
                        full_path = '.'.join(parts[:i]) + f".{key}"
                        if zsh:
                            print(f".{key}\t{full_path}\tkey")
                        else:
                            print(full_path)
                return

            if part == parts[-1].split('.')[-1]:
                # Last part - complete it
                break

            if isinstance(current, (dict, OrderedDict)) and part in current:
                current = current[part]
                completed_parts.append(part)
            else:
                return

        # List keys at current level matching the last part
        last_part = parts[-1]
        if isinstance(current, (dict, OrderedDict)):
            prefix_so_far = '.' + '.'.join(parts[1:-1])
            if prefix_so_far == '.':
                prefix_so_far = ''

            for key in current.keys():
                if key.startswith(last_part):
                    full_path = prefix_so_far + '.' + key
                    if zsh:
                        print(f".{key}\t{full_path}\tkey")
                    else:
                        print(full_path)
    else:
        # No expression yet, list top-level keys
        if isinstance(data, (dict, OrderedDict)):
            for key in data.keys():
                if zsh:
                    print(f".{key}\t.{key}\tkey")
                else:
                    print(f".{key}")

